#!/usr/bin/env python3
"""Fill supplier_contact_template.hwpx using supplier_contact.json.

- Replaces all {{key}} placeholders in extracted XML/text nodes.
- For any <hp:p> paragraph whose text changed, removes <hp:linesegarray>
  children (layout cache) to avoid overlapping characters when opened.
- Writes /root/supplier_contact_ready.hwpx

This script is intentionally conservative: it only rewrites files that actually
contained placeholders and changed.
"""

import json
import os
import re
import shutil
import sys
import zipfile
import xml.etree.ElementTree as ET

TEMPLATE_HWPX = "/root/supplier_contact_template.hwpx"
JSON_PATH = "/root/supplier_contact.json"
WORK_DIR = "/tmp/hwpx_work"
TEMPLATE_ZIP = os.path.join(WORK_DIR, "template.zip")
EXTRACTED_DIR = os.path.join(WORK_DIR, "template_contents")
OUTPUT_HWPX = "/root/supplier_contact_ready.hwpx"

PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")


def flatten(d, parent_key="", sep="."):
    out = {}
    if isinstance(d, dict):
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else str(k)
            if isinstance(v, dict):
                out.update(flatten(v, new_key, sep))
            else:
                out[new_key] = str(v)
    return out


def build_replacement_map(data):
    flat = flatten(data)
    if isinstance(data, dict):
        for k, v in data.items():
            if not isinstance(v, dict):
                flat[str(k)] = str(v)
    return flat


def replace_placeholders(text, replacements):
    def repl(m):
        key = m.group(1).strip()
        if key in replacements:
            return replacements[key]
        # Case-insensitive fallback
        for k, v in replacements.items():
            if k.lower() == key.lower():
                return v
        # Leave as-is (we'll fail verification later if anything remains)
        sys.stderr.write(f"WARNING: No replacement found for placeholder: {{{{{key}}}}}\n")
        return m.group(0)

    return PLACEHOLDER_RE.sub(repl, text)


def localname(tag):
    return tag.split("}", 1)[1] if "}" in tag else tag


def paragraph_ancestors(elem, parent_map):
    cur = elem
    while cur is not None:
        if localname(cur.tag) == "p":
            return cur
        cur = parent_map.get(cur)
    return None


def remove_linesegarray_children(p_elem):
    removed = 0
    for child in list(p_elem):
        if localname(child.tag) == "linesegarray":
            p_elem.remove(child)
            removed += 1
    return removed


def ensure_extracted():
    os.makedirs(WORK_DIR, exist_ok=True)
    shutil.copyfile(TEMPLATE_HWPX, TEMPLATE_ZIP)

    if os.path.exists(EXTRACTED_DIR):
        shutil.rmtree(EXTRACTED_DIR)
    os.makedirs(EXTRACTED_DIR, exist_ok=True)

    with zipfile.ZipFile(TEMPLATE_ZIP) as z:
        z.extractall(EXTRACTED_DIR)


def process_files(replacements):
    modified_files = []

    for root, _dirs, files in os.walk(EXTRACTED_DIR):
        for fname in files:
            fpath = os.path.join(root, fname)

            # HWPX is mostly XML; still keep scope conservative.
            if not (
                fname.endswith(".xml")
                or fname.endswith(".rels")
                or fname.endswith(".hpf")
            ):
                continue

            with open(fpath, "rb") as f:
                raw = f.read()

            # Quick pre-check to avoid rewriting untouched files.
            if b"{{" not in raw:
                continue

            # Try XML parse first.
            try:
                parser = ET.XMLParser(target=ET.TreeBuilder(insert_comments=True))
                root_elem = ET.fromstring(raw, parser=parser)
                tree = ET.ElementTree(root_elem)
            except ET.ParseError:
                # Fallback: do plain UTF-8 replacement for non-XML-ish files.
                text = raw.decode("utf-8", errors="replace")
                new_text = replace_placeholders(text, replacements)
                if new_text != text:
                    with open(fpath, "wb") as f:
                        f.write(new_text.encode("utf-8"))
                    modified_files.append(fpath)
                continue

            parent_map = {child: parent for parent in tree.iter() for child in list(parent)}

            changed_paragraphs = set()
            any_change = False

            for elem in tree.iter():
                if elem.text and "{{" in elem.text:
                    new_text = replace_placeholders(elem.text, replacements)
                    if new_text != elem.text:
                        elem.text = new_text
                        any_change = True
                        p = paragraph_ancestors(elem, parent_map)
                        if p is not None:
                            changed_paragraphs.add(p)

                if elem.tail and "{{" in elem.tail:
                    new_tail = replace_placeholders(elem.tail, replacements)
                    if new_tail != elem.tail:
                        elem.tail = new_tail
                        any_change = True
                        p = paragraph_ancestors(elem, parent_map)
                        if p is not None:
                            changed_paragraphs.add(p)

            if not any_change:
                continue

            # Remove layout-cache elements from changed paragraphs.
            removed_total = 0
            for p in changed_paragraphs:
                removed_total += remove_linesegarray_children(p)

            # Write back.
            with open(fpath, "wb") as f:
                f.write(
                    ET.tostring(
                        tree.getroot(),
                        encoding="UTF-8",
                        xml_declaration=True,
                    )
                )

            modified_files.append(fpath)
            sys.stderr.write(
                f"Modified {fpath} (changed paragraphs={len(changed_paragraphs)}, linesegarray removed={removed_total})\n"
            )

    return modified_files


def verify_no_placeholders_in_dir():
    remaining = []
    for root, _dirs, files in os.walk(EXTRACTED_DIR):
        for fname in files:
            fpath = os.path.join(root, fname)
            try:
                with open(fpath, "rb") as f:
                    raw = f.read()
            except OSError:
                continue
            if b"{{" in raw:
                # show a small excerpt for debugging
                text = raw.decode("utf-8", errors="replace")
                matches = PLACEHOLDER_RE.findall(text)
                if matches:
                    remaining.append((fpath, matches))

    return remaining


def repackage_hwpx():
    if os.path.exists(OUTPUT_HWPX):
        os.remove(OUTPUT_HWPX)

    with zipfile.ZipFile(OUTPUT_HWPX, "w", compression=zipfile.ZIP_DEFLATED) as zf:
        for root, _dirs, files in os.walk(EXTRACTED_DIR):
            for fname in files:
                fpath = os.path.join(root, fname)
                arcname = os.path.relpath(fpath, EXTRACTED_DIR)
                zf.write(fpath, arcname)


def validate_final_package():
    with zipfile.ZipFile(OUTPUT_HWPX) as z:
        names = z.namelist()
        if not names:
            raise RuntimeError("Output package is empty")
        for name in names:
            try:
                content = z.read(name).decode("utf-8", errors="replace")
            except Exception:
                continue
            if "{{" in content:
                matches = PLACEHOLDER_RE.findall(content)
                if matches:
                    raise RuntimeError(f"Placeholders remain in {name}: {matches}")


def main():
    with open(JSON_PATH, "r", encoding="utf-8") as f:
        data = json.load(f)
    replacements = build_replacement_map(data)

    ensure_extracted()

    modified = process_files(replacements)
    sys.stderr.write(f"Modified {len(modified)} file(s).\n")

    remaining = verify_no_placeholders_in_dir()
    if remaining:
        for fpath, matches in remaining:
            sys.stderr.write(f"FAIL: {fpath} still has placeholders: {matches}\n")
        raise SystemExit(2)

    repackage_hwpx()
    validate_final_package()

    print(OUTPUT_HWPX)


if __name__ == "__main__":
    main()

